local _, WFJ = ...
WFJ.Data.add("book", {
  ["3908f6341e5c7b35"] = { "La pace tra orchi e umani fu infranta dall'arrivo di un'immensa flotta dell'⟦Alliance=Alleanza⟧ a Kalimdor. La possente flotta, al comando del grande ammiraglio Daelin Proudmoore (il padre di Jaina), aveva lasciato Lordaeron prima che Arthas distruggesse il regno. Dopo molti mesi estenuanti di navigazione, l'ammiraglio Proudmoore cercava tutti i sopravvissuti dell'⟦Alliance=Alleanza⟧ che riusciva a trovare.", "." },
  ["3939ef54f232c05b"] = { "Elune è con te, {name}. Me lo sussurra il vento, e sono lieta di poter partecipare direttamente alla formazione della nostra prossima generazione di cacciatori.\n\nDa quanto mi è stato detto, ti trovi vicino ad Aldrassil. Vorrei incontrarti dentro il grande albero quando avrai tempo.\n\nI nostri anziani mi hanno affidato il compito di assicurarmi che i nuovi cacciatori vengano addestrati a dovere per le prove che li attendono. Dato che sei tra gli allievi più recenti, ti converrebbe venire a trovarmi. Fino ad allora, stammi bene.\n\n-Ayanna Everstride, istruttrice dei cacciatori", "." },
  ["393a33e1201db54d"] = { "Per quanto fosse difficile crederlo, gli orchi, un tempo considerati la razza più aggressiva mai vista su Azeroth, avevano perso del tutto la volontà di combattere. La strana letargia lasciava perplessi i capi dell'⟦Alliance=Alleanza⟧ e continuava a esigere il suo tributo dagli orchi, che si indebolivano rapidamente.", "." },
  ["3991520fd70b2abe"] = { "--Secondo giorno--\n\nLe terre delle ⟦Barrens=Savane⟧ sono vaste e sconfinate. Il mio cammino è stato lungo e faticoso e finora non ha prodotto nulla di interessante per gli archivi della ⟦Explorers' League=Lega degli Esploratori⟧.\n\nL'unico episodio degno di nota è avvenuto vicino alla strada dell'oro. In lontananza ho notato delle strane creature. Metà maiali e metà uomini, sembrava. Mi sono nascosto in fretta e ho lasciato passare quelle bestie immonde. Che puzza immonda si sono lasciate dietro!", "." },
  ["39efa4e44225b66e"] = { ". . .una rabbia e una furia che non sapevo nemmeno esistessero! Come osa. Mentre spiegavo a Giles il significato dei numeri, Tilloa mi compare davanti con un pretendente, e per giunta mano nella mano in pubblico! Che giovanotto rozzo. Invece di presentarmi come si deve, Tilloa si è limitata a dire: \"Oh, è solo il mio precettore, zio Stalvan. È un vecchietto simpatico.\" Vecchio! A quella parola le guance mi sono avvampate. Ho solo qualche anno più di lei, eppure mi tradisce. . .", "." },
})
